  //#region "TestParseJsonDate"
  function testParseJsonDate(inputDate: string|undefined|null, result: Date | undefined, preserveTimeOfDay?: boolean): void {
    const date = inputDate as string;
    const expectedResult = result as Date;
    const parseDate = parseJsonDate(date, preserveTimeOfDay) as Date;
    if (parseDate instanceof Date) {
      expect(parseDate.getMinutes()).toBe(expectedResult.getMinutes());
      expect(parseDate.getHours()).toBe(expectedResult.getHours());
      expect(parseDate.getDate()).toBe(expectedResult.getDate());
      expect(parseDate.getMonth()).toBe(expectedResult.getMonth());
      expect(parseDate.getFullYear()).toBe(expectedResult.getFullYear());
    } else {
      expect(parseDate).toBe(expectedResult);
    }
  }
  it('It should test the parseJsonDate function', () => {
    testParseJsonDate('2023-07-25 13:10:10', new Date(2023, 6, 25, 13, 10, 10), true);
    testParseJsonDate('2023-05-05 23:59:60', new Date(2023, 4, 5, 23, 59, 60), true);
    testParseJsonDate('2023-02-05 23:59:59', new Date(2023, 1, 5, 23, 59, 59), true);
    testParseJsonDate('2024-02-29 00:00:00', new Date(2024, 1, 29, 0, 0, 0), true);
    testParseJsonDate('2023-08-25 23:59:00', new Date(2023, 7, 25, 23, 59, 0), true);
    testParseJsonDate('2023-02-29 23:59:60', new Date(2023, 1, 29, 23, 59, 60), true);
    testParseJsonDate('2023-07-25 13:10:10', new Date(2023, 6, 25), false);
    testParseJsonDate('2023-05-05 23:59:60', new Date(2023, 4, 5), false);
    testParseJsonDate('2023-02-05 23:59:59', new Date(2023, 1, 5), false);
    testParseJsonDate('2024-02-29 00:00:00', new Date(2024, 1, 29), false);
    testParseJsonDate('2023-08-25 23:59:00', new Date(2023, 7, 25), false);
    testParseJsonDate('2023-02-29 23:59:60', new Date(2023, 1, 29), false);
    testParseJsonDate(null, undefined, false);
    testParseJsonDate(undefined, undefined, false);
    testParseJsonDate(null, undefined, true);
    testParseJsonDate(undefined, undefined, true);
  });
  //#endregion "TestParseJsonDate"

