  it('should test delocalizeDate', () => {
    testIt({format: 'yyyy/dd/MM', localizedDateString: '2025/30/2'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: 'Brian likes ice cream'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '10'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '10/16'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '10/16/2025'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '2025/28/02/'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '.2025/28/02/'}, {outputDateObject: undefined});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '-2025/28/02/'}, {outputDateObject: undefined});

    testIt({format: 'MM/dd/yyyy', localizedDateString: '2/28/2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'MM/yyyy/dd', localizedDateString: '2/2025/28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd/yyyy/MM', localizedDateString: '28/2025/2'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd/MM/yyyy', localizedDateString: '28/2/2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy/MM/dd', localizedDateString: '2025/2/28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '2025/28/2'}, {outputDateObject: new Date('2/28/2025')});

    testIt({format: 'MM-dd-yyyy', localizedDateString: '2-28-2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'MM-yyyy-dd', localizedDateString: '2-2025-28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd-yyyy-MM', localizedDateString: '28-2025-2'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd-MM-yyyy', localizedDateString: '28-2-2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy-MM-dd', localizedDateString: '2025-2-28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy-dd-MM', localizedDateString: '2025-28-2'}, {outputDateObject: new Date('2/28/2025')});

    testIt({format: 'MM.dd.yyyy', localizedDateString: '2.28.2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'MM.yyyy.dd', localizedDateString: '2.2025.28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd.yyyy.MM', localizedDateString: '28.2025.2'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'dd.MM.yyyy', localizedDateString: '28.2.2025'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy.MM.dd', localizedDateString: '2025.2.28'}, {outputDateObject: new Date('2/28/2025')});
    testIt({format: 'yyyy.dd.MM', localizedDateString: '2025.28.2'}, {outputDateObject: new Date('2/28/2025')});


    testIt({format: 'MM/dd/yyyy', localizedDateString: '05/25/1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'MM/yyyy/dd', localizedDateString: '05/1977/25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd/yyyy/MM', localizedDateString: '25/1977/05'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd/MM/yyyy', localizedDateString: '25/05/1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy/MM/dd', localizedDateString: '1977/05/25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy/dd/MM', localizedDateString: '1977/25/05'}, {outputDateObject: new Date('05/25/1977')});

    testIt({format: 'MM-dd-yyyy', localizedDateString: '05-25-1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'MM-yyyy-dd', localizedDateString: '05-1977-25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd-yyyy-MM', localizedDateString: '25-1977-05'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd-MM-yyyy', localizedDateString: '25-05-1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy-MM-dd', localizedDateString: '1977-05-25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy-dd-MM', localizedDateString: '1977-25-05'}, {outputDateObject: new Date('05/25/1977')});

    testIt({format: 'MM.dd.yyyy', localizedDateString: '05.25.1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'MM.yyyy.dd', localizedDateString: '05.1977.25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd.yyyy.MM', localizedDateString: '25.1977.05'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'dd.MM.yyyy', localizedDateString: '25.05.1977'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy.MM.dd', localizedDateString: '1977.05.25'}, {outputDateObject: new Date('05/25/1977')});
    testIt({format: 'yyyy.dd.MM', localizedDateString: '1977.25.05'}, {outputDateObject: new Date('05/25/1977')});


    function testIt(input: {format: string, localizedDateString: string}, output: {outputDateObject: Date | undefined}): void {

      const currentLocale = getCurrentLocale();
      const originalMediumDateFormat = currentLocale.DATETIME_FORMATS.mediumDate;
      currentLocale.DATETIME_FORMATS.mediumDate = input.format;


      const delocalizedDate: Date | undefined = deLocalizeDate(input.localizedDateString);

      if (delocalizedDate != null) {
        if (output.outputDateObject == null) {
          expect(delocalizedDate == null).toBe(true);
        } else {
          const areEqual = delocalizedDate.getTime() === output.outputDateObject.getTime();
          if (!areEqual) {
            console.log(JSON.stringify(input), JSON.stringify(output));
          }
          expect(areEqual).toBe(true);
        }
      } else {
        if (output.outputDateObject != null) {
          expect(delocalizedDate == null).toBe(false);
        } else {
          expect(delocalizedDate == null).toBe(true);
        }
      }


      //Put the format back
      currentLocale.DATETIME_FORMATS.mediumDate = originalMediumDateFormat;





    }



  });

